// La API (POST /api/vuelos/:id/chat, con sesión de admin) manda { action, sessionId, chatInput, vueloId } dentro de "body". Se comprueba antes de gastar saldo del modelo.
const body = ($input.first().json.body) || {};
const chatInput = typeof body.chatInput === 'string' ? body.chatInput.trim() : '';
const sessionId = typeof body.sessionId === 'string' ? body.sessionId.trim() : '';
const vueloId = typeof body.vueloId === 'string' ? body.vueloId.trim() : '';
if (!chatInput) throw new Error('Falta el mensaje (chatInput).');
if (chatInput.length > 4000) throw new Error('El mensaje supera los 4000 caracteres.');
if (!/^[A-Za-z0-9-]{8,64}$/.test(sessionId)) throw new Error('El sessionId no es válido.');
if (!/^[0-9a-fA-F-]{36}$/.test(vueloId)) throw new Error('Falta el vuelo (vueloId) o no es válido.');
return [{ json: { chatInput, sessionId, vueloId } }];

// El modelo a veces copia mal el enlace de descarga (un carácter de menos). Se reemplaza por el enlace real que
// devolvió la herramienta 'generar_informe', y se quitan los pasos intermedios de la respuesta.
const salida = $input.first().json;
let texto = String(salida.output ?? '');
const pasos = Array.isArray(salida.intermediateSteps) ? salida.intermediateSteps : [];
const patronReal = /https?:\/\/[^\s"'\\<>]*informe\?t=\d{10}-[a-f0-9]{48}/g;
let real = null;
for (const p of pasos) {
  const herramienta = p && p.action && p.action.tool;
  if (herramienta !== 'generar_informe') continue;
  const obs = typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation ?? '');
  const hallados = obs.match(patronReal);
  if (hallados) real = hallados[hallados.length - 1];
}
if (real) {
  const patronCopiado = /https?:\/\/[^\s"'<>)\]]*informe\?t=[^\s"'<>)\]]*/g;
  const hay = patronCopiado.test(texto);
  texto = hay ? texto.replace(patronCopiado, real) : texto;
  if (!hay) texto = real + '\n\n' + texto;
}
return [{ json: { output: texto } }];
